    {
      "keystrokes": "echo '=== py2-isms ==='; grep -rnE 'xrange|iteritems|itervalues|has_key|from fractions import gcd|import fractions' /app/pyknotid/pyknotid/ ; echo '=== three_twist def ==='; grep -rn 'def three_twist\\|def trefoil' /app/pyknotid/pyknotid/make/; echo '=== alexander def uses cython? ==='; grep -n 'vassiliev_degree_3\\|def alexander\\|mode ==\|import cinvariants' /app/pyknotid/pyknotid/invariants.py\n",
